INSERT INTO public.questions (topic_id, question_type_id, quiz_type, question, choice_a, choice_b, choice_c, choice_d, correct_answer, explanation, is_active) VALUES
('b0000000-0000-0000-0000-000000000101', 3, 'post_test', 'A change that produces one or more new substances.', NULL, NULL, NULL, NULL, 'Chemical change', 'The correct term is: Chemical change.', true),
('b0000000-0000-0000-0000-000000000101', 3, 'post_test', 'A change that only affects the size, shape, or state of a substance without changing its composition.', NULL, NULL, NULL, NULL, 'Physical change', 'The correct term is: Physical change.', true),
('b0000000-0000-0000-0000-000000000101', 3, 'post_test', 'The process of tomatoes spoiling and producing new substances.', NULL, NULL, NULL, NULL, 'Rotting (rotting of tomatoes)', 'The correct term is: Rotting (rotting of tomatoes).', true),
('b0000000-0000-0000-0000-000000000101', 3, 'post_test', 'The type of change represented by crushing chunks of ice.', NULL, NULL, NULL, NULL, 'Physical change', 'The correct term is: Physical change.', true),
('b0000000-0000-0000-0000-000000000101', 3, 'post_test', 'The main characteristic that distinguishes a chemical change from a physical change.', NULL, NULL, NULL, NULL, 'Formation of a new substance', 'The correct term is: Formation of a new substance.', true),
('b0000000-0000-0000-0000-000000000101', 3, 'post_test', 'The evidence of a chemical reaction shown when vinegar reacts with baking soda and bubbles are produced.', NULL, NULL, NULL, NULL, 'Gas evolution (gas formation)', 'The correct term is: Gas evolution (gas formation).', true),
('b0000000-0000-0000-0000-000000000101', 3, 'post_test', 'The evidence of a chemical reaction shown when milk forms lumpy solids.', NULL, NULL, NULL, NULL, 'Formation of a precipitate', 'The correct term is: Formation of a precipitate.', true),
('b0000000-0000-0000-0000-000000000101', 3, 'post_test', 'The evidence shown when quicklime reacts with water and releases heat.', NULL, NULL, NULL, NULL, 'Temperature change (heat released)', 'The correct term is: Temperature change (heat released).', true),
('b0000000-0000-0000-0000-000000000101', 3, 'post_test', 'The change that occurs when paper is cut into smaller pieces.', NULL, NULL, NULL, NULL, 'Physical change', 'The correct term is: Physical change.', true),
('b0000000-0000-0000-0000-000000000101', 3, 'post_test', 'The evidence of a chemical reaction when a yellow solid forms after mixing two clear solutions.', NULL, NULL, NULL, NULL, 'Precipitate formation', 'The correct term is: Precipitate formation.', true),
('b0000000-0000-0000-0000-000000000101', 3, 'post_test', 'The substances found on the left side of a chemical equation.', NULL, NULL, NULL, NULL, 'Reactants', 'The correct term is: Reactants.', true),
('b0000000-0000-0000-0000-000000000101', 3, 'post_test', 'The substances formed on the right side of a chemical equation.', NULL, NULL, NULL, NULL, 'Products', 'The correct term is: Products.', true),
('b0000000-0000-0000-0000-000000000101', 3, 'post_test', 'The meaning of the symbol (aq) in a chemical equation.', NULL, NULL, NULL, NULL, 'Aqueous (dissolved in water)', 'The correct term is: Aqueous (dissolved in water).', true),
('b0000000-0000-0000-0000-000000000101', 3, 'post_test', 'The meaning of the symbol Δ written above the reaction arrow.', NULL, NULL, NULL, NULL, 'Heat is supplied', 'The correct term is: Heat is supplied.', true),
('b0000000-0000-0000-0000-000000000101', 3, 'post_test', 'The meaning of the downward arrow (↓) in a chemical equation.', NULL, NULL, NULL, NULL, 'Precipitate (solid formed)', 'The correct term is: Precipitate (solid formed).', true),
('b0000000-0000-0000-0000-000000000101', 3, 'post_test', 'The meaning of the plus sign (+) between substances in a chemical equation.', NULL, NULL, NULL, NULL, 'Reacts with / mixed with', 'The correct term is: Reacts with / mixed with.', true),
('b0000000-0000-0000-0000-000000000101', 3, 'post_test', 'The reaction type represented by A + B → AB.', NULL, NULL, NULL, NULL, 'Combination (Synthesis) reaction', 'The correct term is: Combination (Synthesis) reaction.', true),
('b0000000-0000-0000-0000-000000000101', 3, 'post_test', 'The reaction type shown by 2Na + Cl₂ → 2NaCl.', NULL, NULL, NULL, NULL, 'Combination (Synthesis) reaction', 'The correct term is: Combination (Synthesis) reaction.', true),
('b0000000-0000-0000-0000-000000000101', 3, 'post_test', 'The reaction type represented by CaCO₃ → CaO + CO₂.', NULL, NULL, NULL, NULL, 'Decomposition reaction', 'The correct term is: Decomposition reaction.', true),
('b0000000-0000-0000-0000-000000000101', 3, 'post_test', 'The general equation for a decomposition reaction.', NULL, NULL, NULL, NULL, 'AB → A + B', 'The correct term is: AB → A + B.', true),
('b0000000-0000-0000-0000-000000000101', 3, 'post_test', 'The reaction in which one element replaces another element in a compound.', NULL, NULL, NULL, NULL, 'Single displacement reaction', 'The correct term is: Single displacement reaction.', true),
