('b0000000-0000-0000-0000-000000000101', 3, 'post_test', 'The two products always formed during the complete combustion of a hydrocarbon.', NULL, NULL, NULL, NULL, 'Carbon dioxide (CO₂) and water (H₂O)', 'The correct term is: Carbon dioxide (CO₂) and water (H₂O).', true),
('b0000000-0000-0000-0000-000000000101', 3, 'post_test', 'The reaction represented by HBr + NaOH → NaBr + H₂O.', NULL, NULL, NULL, NULL, 'Neutralization (Acid–Base reaction)', 'The correct term is: Neutralization (Acid–Base reaction).', true),
('b0000000-0000-0000-0000-000000000101', 3, 'post_test', 'The special type of double displacement reaction involving an acid and a base.', NULL, NULL, NULL, NULL, 'Neutralization', 'The correct term is: Neutralization.', true),
('b0000000-0000-0000-0000-000000000101', 3, 'post_test', 'The type of change represented by melting wax.', NULL, NULL, NULL, NULL, 'Physical change', 'The correct term is: Physical change.', true),
('b0000000-0000-0000-0000-000000000101', 3, 'post_test', 'The process represented by dissolving salt in water.', NULL, NULL, NULL, NULL, 'Physical change', 'The correct term is: Physical change.', true),
('b0000000-0000-0000-0000-000000000101', 3, 'post_test', 'In the equation Mg + O₂ → MgO, the substance MgO is called the ________.', NULL, NULL, NULL, NULL, 'Product', 'The correct term is: Product.', true),
('b0000000-0000-0000-0000-000000000101', 3, 'post_test', 'The meaning of the reaction arrow (→) in a chemical equation.', NULL, NULL, NULL, NULL, 'Yields / Produces', 'The correct term is: Yields / Produces.', true);
