('b0000000-0000-0000-0000-000000000104', 3, 'post_test', 'Balance the equation: __ H₂ + __ O₂ → __ H₂O.', NULL, NULL, NULL, NULL, '2, 1, 2', 'The correct term is: 2, 1, 2.', true),
('b0000000-0000-0000-0000-000000000104', 3, 'post_test', 'Balance the equation: __ N₂ + __ H₂ → __ NH₃.', NULL, NULL, NULL, NULL, '1, 3, 2', 'The correct term is: 1, 3, 2.', true),
('b0000000-0000-0000-0000-000000000104', 3, 'post_test', 'Balance the equation: __ Al + __ O₂ → __ Al₂O₃.', NULL, NULL, NULL, NULL, '4, 3, 2', 'The correct term is: 4, 3, 2.', true);
INSERT INTO public.questions (topic_id, question_type_id, quiz_type, question, choice_a, choice_b, choice_c, choice_d, correct_answer, explanation, is_active) VALUES
('b0000000-0000-0000-0000-000000000106', 3, 'post_test', 'The measure of how fast a chemical reaction occurs.', NULL, NULL, NULL, NULL, 'Reaction rate', 'The correct term is: Reaction rate.', true),
('b0000000-0000-0000-0000-000000000106', 3, 'post_test', 'The factor that generally increases reaction rate by increasing particle movement.', NULL, NULL, NULL, NULL, 'Temperature', 'The correct term is: Temperature.', true),
('b0000000-0000-0000-0000-000000000106', 3, 'post_test', 'A substance that speeds up a reaction without being consumed.', NULL, NULL, NULL, NULL, 'Catalyst', 'The correct term is: Catalyst.', true),
('b0000000-0000-0000-0000-000000000106', 3, 'post_test', 'A reaction that releases heat to its surroundings.', NULL, NULL, NULL, NULL, 'Exothermic reaction', 'The correct term is: Exothermic reaction.', true),
('b0000000-0000-0000-0000-000000000106', 3, 'post_test', 'A reaction that absorbs heat from its surroundings.', NULL, NULL, NULL, NULL, 'Endothermic reaction', 'The correct term is: Endothermic reaction.', true),
('b0000000-0000-0000-0000-000000000106', 3, 'post_test', 'The factor increased when a solid reactant is crushed into smaller pieces.', NULL, NULL, NULL, NULL, 'Surface area', 'The correct term is: Surface area.', true),
('b0000000-0000-0000-0000-000000000106', 3, 'post_test', 'The three components of the fire triangle.', NULL, NULL, NULL, NULL, 'Fuel, oxygen, and heat (ignition temperature)', 'The correct term is: Fuel, oxygen, and heat (ignition temperature).', true),
('b0000000-0000-0000-0000-000000000106', 3, 'post_test', 'The factor responsible for slowing food spoilage inside a refrigerator.', NULL, NULL, NULL, NULL, 'Lower temperature', 'The correct term is: Lower temperature.', true),
('b0000000-0000-0000-0000-000000000106', 3, 'post_test', 'A substance that slows down a chemical reaction.', NULL, NULL, NULL, NULL, 'Inhibitor', 'The correct term is: Inhibitor.', true),
('b0000000-0000-0000-0000-000000000106', 3, 'post_test', 'A common example of an exothermic reaction.', NULL, NULL, NULL, NULL, 'Combustion (burning wood)', 'The correct term is: Combustion (burning wood).', true),
('b0000000-0000-0000-0000-000000000106', 3, 'post_test', 'The minimum amount of energy required for a reaction to begin.', NULL, NULL, NULL, NULL, 'Activation energy', 'The correct term is: Activation energy.', true),
('b0000000-0000-0000-0000-000000000106', 3, 'post_test', 'The theory stating that particles must collide with enough energy and proper orientation for a reaction to occur.', NULL, NULL, NULL, NULL, 'Collision theory', 'The correct term is: Collision theory.', true),
('b0000000-0000-0000-0000-000000000106', 3, 'post_test', 'The effect of crushing a solid reactant on its reaction rate.', NULL, NULL, NULL, NULL, 'Increases the reaction rate', 'The correct term is: Increases the reaction rate.', true),
('b0000000-0000-0000-0000-000000000106', 3, 'post_test', 'The effect of lowering temperature on most chemical reactions.', NULL, NULL, NULL, NULL, 'Slows the reaction rate', 'The correct term is: Slows the reaction rate.', true),
('b0000000-0000-0000-0000-000000000106', 3, 'post_test', 'Powdered calcium carbonate reacts faster than marble chips because it has greater __________.', NULL, NULL, NULL, NULL, 'Surface area', 'The correct term is: Surface area.', true),
('b0000000-0000-0000-0000-000000000106', 3, 'post_test', 'Concentrated hydrochloric acid reacts faster than dilute hydrochloric acid because of higher __________.', NULL, NULL, NULL, NULL, 'Concentration', 'The correct term is: Concentration.', true),
('b0000000-0000-0000-0000-000000000106', 3, 'post_test', 'Biological catalysts found in living organisms.', NULL, NULL, NULL, NULL, 'Enzymes', 'The correct term is: Enzymes.', true),
('b0000000-0000-0000-0000-000000000106', 3, 'post_test', 'Water extinguishes fire mainly by removing __________.', NULL, NULL, NULL, NULL, 'Heat', 'The correct term is: Heat.', true),
('b0000000-0000-0000-0000-000000000106', 3, 'post_test', 'A fire blanket extinguishes fire by removing __________.', NULL, NULL, NULL, NULL, 'Oxygen', 'The correct term is: Oxygen.', true),
('b0000000-0000-0000-0000-000000000106', 3, 'post_test', 'Painting or galvanizing iron prevents rust by blocking contact with __________ and __________.', NULL, NULL, NULL, NULL, 'Oxygen and water (moisture)', 'The correct term is: Oxygen and water (moisture).', true),
('b0000000-0000-0000-0000-000000000106', 3, 'post_test', 'The food preservation method that removes water needed by microorganisms.', NULL, NULL, NULL, NULL, 'Drying, salting, or sugaring', 'The correct term is: Drying, salting, or sugaring.', true),
('b0000000-0000-0000-0000-000000000106', 3, 'post_test', 'The food preservation method that kills microorganisms with heat and seals out oxygen.', NULL, NULL, NULL, NULL, 'Canning', 'The correct term is: Canning.', true),
('b0000000-0000-0000-0000-000000000106', 3, 'post_test', 'Stirring reactants usually has what effect on reaction rate?', NULL, NULL, NULL, NULL, 'Speeds up the reaction', 'The correct term is: Speeds up the reaction.', true),
('b0000000-0000-0000-0000-000000000106', 3, 'post_test', 'A process that continuously absorbs energy from sunlight.', NULL, NULL, NULL, NULL, 'Photosynthesis', 'The correct term is: Photosynthesis.', true),
('b0000000-0000-0000-0000-000000000106', 3, 'post_test', 'The way a catalyst speeds up a reaction.', NULL, NULL, NULL, NULL, 'By lowering the activation energy', 'The correct term is: By lowering the activation energy.', true),
('b0000000-0000-0000-0000-000000000106', 3, 'post_test', 'The reason higher temperatures greatly increase reaction rate.', NULL, NULL, NULL, NULL, 'More frequent collisions and more particles have enough energy to react', 'The correct term is: More frequent collisions and more particles have enough energy to react.', true),
('b0000000-0000-0000-0000-000000000106', 3, 'post_test', 'The reason explosions occur extremely rapidly.', NULL, NULL, NULL, NULL, 'Instant gas release, heat, and large surface contact', 'The correct term is: Instant gas release, heat, and large surface contact.', true),
('b0000000-0000-0000-0000-000000000106', 3, 'post_test', 'Why does a reaction eventually stop after all reactants are used up?', NULL, NULL, NULL, NULL, 'The reactants are completely used up, so no more effective collisions occur', 'The correct term is: The reactants are completely used up, so no more effective collisions occur.', true),
('b0000000-0000-0000-0000-000000000106', 3, 'post_test', 'The device in vehicles that uses catalysts to reduce harmful exhaust gases.', NULL, NULL, NULL, NULL, 'Catalytic converter', 'The correct term is: Catalytic converter.', true),
('b0000000-0000-0000-0000-000000000106', 3, 'post_test', 'The factor increased when oxygen concentration becomes higher, causing fire to burn faster.', NULL, NULL, NULL, NULL, 'Concentration of oxygen (reactant concentration)', 'The correct term is: Concentration of oxygen (reactant concentration).', true);
INSERT INTO public.questions (topic_id, question_type_id, quiz_type, question, choice_a, choice_b, choice_c, choice_d, correct_answer, explanation, is_active) VALUES
('b0000000-0000-0000-0000-000000000107', 3, 'post_test', 'The process of maintaining a stable internal environment despite external changes.', NULL, NULL, NULL, NULL, 'Homeostasis', 'The correct term is: Homeostasis.', true),
('b0000000-0000-0000-0000-000000000107', 3, 'post_test', 'The two body systems that serve as the main control systems for homeostasis.', NULL, NULL, NULL, NULL, 'Nervous system and Endocrine system', 'The correct term is: Nervous system and Endocrine system.', true),
('b0000000-0000-0000-0000-000000000107', 3, 'post_test', 'The type of feedback mechanism that reverses a change and returns the body to its normal condition.', NULL, NULL, NULL, NULL, 'Negative feedback', 'The correct term is: Negative feedback.', true),
('b0000000-0000-0000-0000-000000000107', 3, 'post_test', 'The normal or target value maintained by the body during homeostasis.', NULL, NULL, NULL, NULL, 'Set point', 'The correct term is: Set point.', true),
('b0000000-0000-0000-0000-000000000107', 3, 'post_test', 'The structure that detects changes in the internal or external environment.', NULL, NULL, NULL, NULL, 'Receptor (Sensor)', 'The correct term is: Receptor (Sensor).', true),
('b0000000-0000-0000-0000-000000000107', 3, 'post_test', 'The structure that carries out the response to restore balance.', NULL, NULL, NULL, NULL, 'Effector', 'The correct term is: Effector.', true),
('b0000000-0000-0000-0000-000000000107', 3, 'post_test', 'The main function of negative feedback in the body.', NULL, NULL, NULL, NULL, 'Reverse the change and restore the set point', 'The correct term is: Reverse the change and restore the set point.', true),
('b0000000-0000-0000-0000-000000000107', 3, 'post_test', 'The body characteristic that is not maintained by homeostasis according to the lesson.', NULL, NULL, NULL, NULL, 'Constant body height', 'The correct term is: Constant body height.', true),
('b0000000-0000-0000-0000-000000000107', 3, 'post_test', 'The part of the brain responsible for regulating body temperature.', NULL, NULL, NULL, NULL, 'Hypothalamus', 'The correct term is: Hypothalamus.', true),
('b0000000-0000-0000-0000-000000000107', 3, 'post_test', 'The response of blood vessels in the skin when the body is cold.', NULL, NULL, NULL, NULL, 'Vasoconstriction (blood vessels constrict)', 'The correct term is: Vasoconstriction (blood vessels constrict).', true),
('b0000000-0000-0000-0000-000000000107', 3, 'post_test', 'The body system that uses hormones as chemical messengers.', NULL, NULL, NULL, NULL, 'Endocrine system', 'The correct term is: Endocrine system.', true),
('b0000000-0000-0000-0000-000000000107', 3, 'post_test', 'The two hormones responsible for regulating blood glucose levels.', NULL, NULL, NULL, NULL, 'Insulin and Glucagon', 'The correct term is: Insulin and Glucagon.', true),
('b0000000-0000-0000-0000-000000000107', 3, 'post_test', 'The hormone released by the pancreas when blood sugar becomes too high.', NULL, NULL, NULL, NULL, 'Insulin', 'The correct term is: Insulin.', true),
('b0000000-0000-0000-0000-000000000107', 3, 'post_test', 'The hormone released by the pancreas when blood sugar becomes too low.', NULL, NULL, NULL, NULL, 'Glucagon', 'The correct term is: Glucagon.', true),
('b0000000-0000-0000-0000-000000000107', 3, 'post_test', 'The organ that regulates water and salt balance by adjusting urine concentration.', NULL, NULL, NULL, NULL, 'Kidneys', 'The correct term is: Kidneys.', true),
('b0000000-0000-0000-0000-000000000107', 3, 'post_test', 'The body''s response that generates heat when a person feels cold.', NULL, NULL, NULL, NULL, 'Shivering', 'The correct term is: Shivering.', true),
('b0000000-0000-0000-0000-000000000107', 3, 'post_test', 'The type of feedback mechanism demonstrated by shivering.', NULL, NULL, NULL, NULL, 'Negative feedback', 'The correct term is: Negative feedback.', true),
('b0000000-0000-0000-0000-000000000107', 3, 'post_test', 'The relationship between insulin and glucagon in regulating blood sugar.', NULL, NULL, NULL, NULL, 'Opposing negative feedback', 'The correct term is: Opposing negative feedback.', true),
('b0000000-0000-0000-0000-000000000107', 3, 'post_test', 'The type of feedback mechanism that amplifies a change away from the set point.', NULL, NULL, NULL, NULL, 'Positive feedback', 'The correct term is: Positive feedback.', true),
('b0000000-0000-0000-0000-000000000107', 3, 'post_test', 'The hormone released after eating to lower blood glucose levels.', NULL, NULL, NULL, NULL, 'Insulin', 'The correct term is: Insulin.', true),
('b0000000-0000-0000-0000-000000000107', 3, 'post_test', 'The organ that mainly removes waste while helping regulate body fluids.', NULL, NULL, NULL, NULL, 'Kidneys', 'The correct term is: Kidneys.', true),
('b0000000-0000-0000-0000-000000000107', 3, 'post_test', 'The two body responses that help lower body temperature when a person becomes too hot.', NULL, NULL, NULL, NULL, 'Sweating and vasodilation', 'The correct term is: Sweating and vasodilation.', true),
('b0000000-0000-0000-0000-000000000107', 3, 'post_test', 'A common example of positive feedback in the human body.', NULL, NULL, NULL, NULL, 'Blood clotting', 'The correct term is: Blood clotting.', true),
('b0000000-0000-0000-0000-000000000107', 3, 'post_test', 'Homeostasis requires a constant supply of what to maintain balance?', NULL, NULL, NULL, NULL, 'Energy', 'The correct term is: Energy.', true),
('b0000000-0000-0000-0000-000000000107', 3, 'post_test', 'If blood pH is not properly maintained, what happens first to many enzymes?', NULL, NULL, NULL, NULL, 'They denature or stop functioning properly', 'The correct term is: They denature or stop functioning properly.', true),
('b0000000-0000-0000-0000-000000000107', 3, 'post_test', 'During exercise, breathing rate increases to maintain the balance of which two gases?', NULL, NULL, NULL, NULL, 'Oxygen (O₂) and Carbon dioxide (CO₂)', 'The correct term is: Oxygen (O₂) and Carbon dioxide (CO₂).', true),
('b0000000-0000-0000-0000-000000000107', 3, 'post_test', 'Arrange the correct sequence of a homeostatic feedback loop.', NULL, NULL, NULL, NULL, 'Stimulus → Receptor → Control Center → Effector → Response', 'The correct term is: Stimulus → Receptor → Control Center → Effector → Response.', true),
('b0000000-0000-0000-0000-000000000107', 3, 'post_test', 'The hormone that strengthens uterine contractions during childbirth through positive feedback.', NULL, NULL, NULL, NULL, 'Oxytocin', 'The correct term is: Oxytocin.', true),
('b0000000-0000-0000-0000-000000000107', 3, 'post_test', 'The long-term result if homeostasis fails to maintain stable internal conditions.', NULL, NULL, NULL, NULL, 'Disease, organ damage, or death', 'The correct term is: Disease, organ damage, or death.', true),
('b0000000-0000-0000-0000-000000000107', 3, 'post_test', 'The active process that continuously keeps the body''s internal environment stable.', NULL, NULL, NULL, NULL, 'Homeostasis', 'The correct term is: Homeostasis.', true);
INSERT INTO public.questions (topic_id, question_type_id, quiz_type, question, choice_a, choice_b, choice_c, choice_d, correct_answer, explanation, is_active) VALUES
('b0000000-0000-0000-0000-000000000108', 3, 'post_test', 'The gradual change in the inherited traits of a population over many generations.', NULL, NULL, NULL, NULL, 'Evolution', 'The correct term is: Evolution.', true),
('b0000000-0000-0000-0000-000000000108', 3, 'post_test', 'The scientist who proposed natural selection as the primary mechanism of evolution.', NULL, NULL, NULL, NULL, 'Charles Darwin', 'The correct term is: Charles Darwin.', true),
('b0000000-0000-0000-0000-000000000108', 3, 'post_test', 'The process in which organisms best adapted to their environment survive and reproduce.', NULL, NULL, NULL, NULL, 'Natural selection', 'The correct term is: Natural selection.', true),
('b0000000-0000-0000-0000-000000000108', 3, 'post_test', 'An inherited characteristic that helps an organism survive and reproduce in its environment.', NULL, NULL, NULL, NULL, 'Adaptation', 'The correct term is: Adaptation.', true),
('b0000000-0000-0000-0000-000000000108', 3, 'post_test', 'The natural differences in traits among individuals of the same species.', NULL, NULL, NULL, NULL, 'Variation', 'The correct term is: Variation.', true),
('b0000000-0000-0000-0000-000000000108', 3, 'post_test', 'The passing of genetic traits from parents to offspring.', NULL, NULL, NULL, NULL, 'Heredity (Inheritance)', 'The correct term is: Heredity (Inheritance).', true),
('b0000000-0000-0000-0000-000000000108', 3, 'post_test', 'Preserved remains, traces, or impressions of ancient organisms found in rocks.', NULL, NULL, NULL, NULL, 'Fossils', 'The correct term is: Fossils.', true),
('b0000000-0000-0000-0000-000000000108', 3, 'post_test', 'Body parts with similar internal structures but different functions due to common ancestry.', NULL, NULL, NULL, NULL, 'Homologous structures', 'The correct term is: Homologous structures.', true),
('b0000000-0000-0000-0000-000000000108', 3, 'post_test', 'A reduced structure that has lost most or all of its original function through evolution.', NULL, NULL, NULL, NULL, 'Vestigial structure', 'The correct term is: Vestigial structure.', true),
('b0000000-0000-0000-0000-000000000108', 3, 'post_test', 'The study of the geographic distribution of living organisms.', NULL, NULL, NULL, NULL, 'Biogeography', 'The correct term is: Biogeography.', true),
('b0000000-0000-0000-0000-000000000108', 3, 'post_test', 'The famous example of evolution involving light and dark peppered moths during the Industrial Revolution.', NULL, NULL, NULL, NULL, 'Natural selection (Peppered moth example)', 'The correct term is: Natural selection (Peppered moth example).', true),
('b0000000-0000-0000-0000-000000000108', 3, 'post_test', 'The type of isolation that occurs when a physical barrier separates populations.', NULL, NULL, NULL, NULL, 'Geographic isolation', 'The correct term is: Geographic isolation.', true),
('b0000000-0000-0000-0000-000000000108', 3, 'post_test', 'Structures that perform the same function but have different evolutionary origins.', NULL, NULL, NULL, NULL, 'Analogous structures', 'The correct term is: Analogous structures.', true),
('b0000000-0000-0000-0000-000000000108', 3, 'post_test', 'The process that prevents gene flow between separated populations, leading to the formation of new species.', NULL, NULL, NULL, NULL, 'Reproductive isolation', 'The correct term is: Reproductive isolation.', true),
('b0000000-0000-0000-0000-000000000108', 3, 'post_test', 'Fossils found in deeper rock layers are generally __________ than those in younger layers.', NULL, NULL, NULL, NULL, 'Simpler and more different from modern organisms', 'The correct term is: Simpler and more different from modern organisms.', true),
('b0000000-0000-0000-0000-000000000108', 3, 'post_test', 'The evolutionary explanation for the long necks of giraffes.', NULL, NULL, NULL, NULL, 'Natural selection favored longer-necked giraffes over many generations', 'The correct term is: Natural selection favored longer-necked giraffes over many generations.', true),
('b0000000-0000-0000-0000-000000000108', 3, 'post_test', 'The process in which humans choose organisms with desirable traits for breeding.', NULL, NULL, NULL, NULL, 'Artificial selection', 'The correct term is: Artificial selection.', true),
('b0000000-0000-0000-0000-000000000108', 3, 'post_test', 'The study of similarities in the early development of embryos as evidence for evolution.', NULL, NULL, NULL, NULL, 'Comparative embryology', 'The correct term is: Comparative embryology.', true),
('b0000000-0000-0000-0000-000000000108', 3, 'post_test', 'The type of isolation that occurs when populations do not interbreed because of differences in behavior or breeding time.', NULL, NULL, NULL, NULL, 'Reproductive isolation', 'The correct term is: Reproductive isolation.', true),
('b0000000-0000-0000-0000-000000000108', 3, 'post_test', 'A species found naturally in only one geographic location.', NULL, NULL, NULL, NULL, 'Endemic species', 'The correct term is: Endemic species.', true),
('b0000000-0000-0000-0000-000000000108', 3, 'post_test', 'The process through which new species are formed.', NULL, NULL, NULL, NULL, 'Speciation', 'The correct term is: Speciation.', true),
('b0000000-0000-0000-0000-000000000108', 3, 'post_test', 'The primary mechanism of evolution that consistently produces adaptations suited to the environment.', NULL, NULL, NULL, NULL, 'Natural selection', 'The correct term is: Natural selection.', true),
('b0000000-0000-0000-0000-000000000108', 3, 'post_test', 'Tiny unused pelvic bones in modern whales are an example of what type of evolutionary evidence?', NULL, NULL, NULL, NULL, 'Vestigial structure', 'The correct term is: Vestigial structure.', true),
('b0000000-0000-0000-0000-000000000108', 3, 'post_test', 'In science, a well-tested explanation supported by extensive evidence is called a __________.', NULL, NULL, NULL, NULL, 'Scientific theory', 'The correct term is: Scientific theory.', true),
('b0000000-0000-0000-0000-000000000108', 3, 'post_test', 'The supercontinent whose existence is supported by matching fossils found in South America and Africa.', NULL, NULL, NULL, NULL, 'Pangaea', 'The correct term is: Pangaea.', true),
('b0000000-0000-0000-0000-000000000108', 3, 'post_test', 'A condition required for natural selection in which inherited differences already exist within a population.', NULL, NULL, NULL, NULL, 'Variation', 'The correct term is: Variation.', true),
('b0000000-0000-0000-0000-000000000108', 3, 'post_test', 'Homologous structures provide evidence that different species share a __________.', NULL, NULL, NULL, NULL, 'Common ancestor', 'The correct term is: Common ancestor.', true),
('b0000000-0000-0000-0000-000000000108', 3, 'post_test', 'During a long drought, finches with larger beaks survived better because of __________.', NULL, NULL, NULL, NULL, 'Natural selection', 'The correct term is: Natural selection.', true),
('b0000000-0000-0000-0000-000000000108', 3, 'post_test', 'The movement of individuals between populations that keeps their gene pools similar.', NULL, NULL, NULL, NULL, 'Gene flow', 'The correct term is: Gene flow.', true),
('b0000000-0000-0000-0000-000000000108', 3, 'post_test', 'The strongest evidence for evolution comes from multiple independent lines of evidence, including fossils, homologous structures, DNA similarity, and __________.', NULL, NULL, NULL, NULL, 'Biogeography', 'The correct term is: Biogeography.', true);
